using System;using System.Linq;using System.Threading.Tasks;using UnityEngine;using AntColony.Units;using AntColony.Core;
public static class Final1113FaceDebug {public static async Task<string> Run(){AntColony.UI.SimulationPause.UserSpeed(0);var c=CommanderRoster.Instance.Commanders.First(x=>x&&x.IsColonyMember);var p=c.GetComponent<MeshyNativeMotionPlayer>();p.PreviewMotion="Idle_3";p.PreviewPhase=.3f;var f=c.transform.Find("Kemono").GetComponentsInChildren<SkinnedMeshRenderer>().First(s=>s.name.StartsWith("Part_Face_"));for(int i=0;i<f.sharedMesh.blendShapeCount;i++)f.SetBlendShapeWeight(i,f.sharedMesh.GetBlendShapeName(i)=="Sleep"?100:0);await Task.Delay(200);var n=p.NativeModel.GetComponentsInChildren<SkinnedMeshRenderer>().First(s=>s.name.StartsWith("Part_Face_"));var d=new Vector3[n.sharedMesh.vertexCount];n.sharedMesh.GetBlendShapeFrameVertices(n.sharedMesh.GetBlendShapeIndex("Sleep"),0,d,null,null);return "source "+string.Join(",",Enumerable.Range(0,f.sharedMesh.blendShapeCount).Select(i=>f.sharedMesh.GetBlendShapeName(i)+":"+f.GetBlendShapeWeight(i)))+" native "+string.Join(",",Enumerable.Range(0,n.sharedMesh.blendShapeCount).Select(i=>n.sharedMesh.GetBlendShapeName(i)+":"+n.GetBlendShapeWeight(i)))+" dy="+d.Min(v=>v.y)+".."+d.Max(v=>v.y);}}
